#define ZANAC_DISPATCH_COUNT (sizeof(zanac_dispatch_table) / sizeof(zanac_dispatch_table[0]))

void zanac_call_at_missing(uint16_t addr)
{
    long pumps = 0, dispatches = 0, frames = 0;
    neslib_debug_counts(&pumps, &dispatches, &frames);
    fprintf(stderr, "zanac: no ported procedure at $%04X (bank=%d 1E/1F=%02X%02X) "
            "(A=%02X X=%02X Y=%02X slot=%02X type=%02X flags=%02X frame=%ld)\n",
            (unsigned)addr, (int)zanac_bank(), (unsigned)MEM8(0x1F), (unsigned)MEM8(0x1E),
            (unsigned)A, (unsigned)X, (unsigned)Y,
            (unsigned)MEM8(0x6A), (unsigned)MEM8(0x40),
            (unsigned)MEM8(0x2B), frames);
}

void zanac_call_at(uint16_t addr)
{
    size_t lo = 0, hi = ZANAC_DISPATCH_COUNT;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (zanac_dispatch_table[mid].addr == addr) {
            zanac_dispatch_table[mid].fn();
            return;
        }
        if (zanac_dispatch_table[mid].addr < addr) lo = mid + 1;
        else hi = mid;
    }
    zanac_call_at_missing(addr);
}
